var i=s=>`<mi>${s}</mi>`,t=s=>`<mo>${s}</mo>`,a=i("HVPG")+t("=")+'<mi class="eq-wedge">WHVP</mi>'+t("\u2212")+'<mi class="eq-hv">FHVP</mi>',r=[{id:"pvt",name:"Portal vein thrombosis"},{id:"presin",name:"Schistosomiasis"},{id:"sin",name:"Cirrhosis"},{id:"postsin",name:"Sinusoidal obstr. synd."},{id:"post",name:"Budd\u2013Chiari syndrome"},{id:"cardiac",name:"Right heart failure"}],o=[{id:"pvt",title:"Portal vein thrombosis"},{id:"presin",title:"Schistosomiasis"},{id:"sin",title:"Cirrhosis"},{id:"postsin",title:"Sinusoidal obstruction syndrome",name:"Sinusoidal obstr. synd."},{id:"post",title:"Budd\u2013Chiari syndrome"},{id:"cardiac",title:"Right heart failure"}],e={kind:"profile"},n={id:"sites",level:"core",title:"Sites and causes of portal hypertension",minutes:15,summary:"Six levels of resistance, each with its pressure profile from the splanchnic veins to the right atrium and its HVPG. Ends with a comparison table.",sections:[["Portal hypertension",["Portal hypertension","Reference"]],["Before the liver",["Pre-hepatic"]],["In the liver",["Intrahepatic \xB7 presinusoidal","Intrahepatic \xB7 sinusoidal","Intrahepatic \xB7 postsinusoidal"]],["After the liver",["Post-hepatic","Cardiac"]],["Telling them apart",["How to tell them apart"]]],objectives:["Place a cause of portal hypertension at one of six levels","Predict the HVPG for resistance at each level","Read a pressure profile to locate the largest pressure drop"],checks:[["Portal vein thrombosis raises the portal pressure. What happens to the HVPG?","It stays normal. The WHVP reflects normal sinusoids, downstream of the thrombus."],["Cirrhosis raises the portal pressure. Does the HVPG rise too?","Yes. The resistance is in the sinusoids, and the wedged pressure reflects sinusoidal pressure."],["Right heart failure and cirrhosis both raise the portal pressure. Which measurements distinguish them?","In right heart failure the right atrial pressure is high and the HVPG is normal. In cirrhosis the right atrial pressure is normal and the HVPG is high."]],slides:[{id:"overview",preset:"healthy",lens:"system",cam:"fit",labels:["CONF","SIN_R","RHV","RA"],rail:"all",glow:[["V_INT","V_SPL","V_IMV"],["PVH_R","PVH_L"],["SIN_RR","SIN_LL"],["RHV_IVC","MHV_IVC","LHV_IVC"],"IVCS_RA"],glowSeq:550,steps:!0,kicker:"Portal hypertension",title:"Portal hypertension is named for the site of resistance",line:"Blood flows from the splanchnic veins {#1} through the portal vein {#2} and sinusoids {#3} to the hepatic veins {#4} and right atrium {#5}. Resistance anywhere raises upstream pressure.",notes:"The figure is colored by vein system: portal veins in one color, systemic veins in another, collaterals and shunts in a third. The numbers light in turn along the route: the mesenteric and splenic veins (the SMV, splenic vein and IMV), the portal vein into both lobes, the sinusoids of both lobes, the three hepatic veins, and the IVC to the right atrium. Portal hypertension is named for the level of resistance. Two levels lie before the sinusoids (pre-hepatic and presinusoidal), one is the sinusoids themselves, and three come after them (postsinusoidal, post-hepatic and cardiac). The level determines which pressures rise, what the HVPG shows, whether varices form and whether ascites develops. Portal hypertension is a portal pressure gradient >5 mmHg; \u226510 mmHg is clinically significant.",ask:["Name one cause of portal hypertension at each level.","Portal vein thrombosis; schistosomiasis; cirrhosis; sinusoidal obstruction syndrome; Budd\u2013Chiari syndrome; right heart failure."]},{id:"healthy",lens:"drop",cam:"route",labels:["CONF","SIN_R","RHV","RA"],tool:e,data:"tiles",tiles:["whvp","fhvp","hvpg"],key:["hvpg"],kicker:"Reference",title:"In a healthy liver each pressure drop is small",eq:[a],line:"The HVPG is wedged [sinusoidal pressure](sin) minus free [hepatic vein](fhvp) pressure: normally 1 to 5 mmHg, {hvpg} here. Pressure falls little from the [portal vein](pv) to the [right atrium](ra).",notes:"The wedged hepatic venous pressure (WHVP) is recorded with a balloon catheter occluding a hepatic vein: with flow stopped, the static column of blood transmits the sinusoidal pressure. The free hepatic venous pressure (FHVP) is recorded with the balloon deflated. HVPG = WHVP \u2212 FHVP. A normal HVPG is 1 to 5 mmHg; >5 mmHg is portal hypertension; from 10 mmHg, clinically significant portal hypertension, varices and decompensation become possible, and the risk rises with the gradient; from about 12 mmHg the risk of variceal bleeding rises. The portal pressure gradient (PPG) is the portal vein pressure minus the IVC pressure, measured directly. The profile in the data card runs from the splanchnic veins to the right atrium: the HVPG bracket under the station names runs from the sinusoids, which the WHVP reflects, to the hepatic vein.",ask:["What does the wedged pressure measure?","The sinusoidal pressure: with the vein occluded, the static column of blood transmits the upstream pressure."]},{id:"pvt",lens:"drop",preset:"pvt-chronic",cam:"portal",labels:["CONF","SV"],terms:{"portal pressure":"pv","wedged pressure":"whvp"},mark:{edges:["PV_TRUNK"],label:"Clot"},tool:e,key:["hvpg","ppg"],kicker:"Pre-hepatic",site:"pre",title:"Portal vein thrombosis: the PPG is high, the HVPG normal",vignette:"A 38-year-old man with a JAK2-positive myeloproliferative neoplasm has splenomegaly and esophageal varices on EGD. His liver tests are normal, and there is no ascites.",line:"Portal pressure is high, yet the wedged pressure and HVPG are normal: the catheter is wedged downstream of the thrombus.",notes:"Chronic thrombosis leads to cavernous transformation of the portal vein: a network of small collaterals around the occluded trunk that still carries portal blood to the liver. The liver parenchyma is normal, so synthetic function is preserved and ascites is uncommon, while varices and splenomegaly are common. Doppler ultrasound or CT shows the thrombus or the cavernoma. The HVPG is normal because the WHVP reflects the sinusoids, downstream of the thrombus; the PPG is high. On the profile the pressure drop is between the splanchnic veins and the portal venules, upstream of the sinusoids that the WHVP reflects. The usual causes are cirrhosis, a myeloproliferative neoplasm or another thrombophilia, pancreatitis or abdominal sepsis, and liver or pancreatic cancer.",ask:["Why is the HVPG normal when the portal pressure is about 20 mmHg?","The WHVP reflects the sinusoids, which are downstream of the thrombus and at normal pressure."]},{id:"presin",lens:"drop",terms:{"portal venules":"lobule:triad",sinusoids:"lobule:sinusoid"},preset:"schisto",cam:"lobule:triad",tool:e,key:["pv","hvpg","ppg"],callout:{at:"triad",label:"Resistance"},scales:{anatomy:{cam:"liver",labels:["CONF","SIN_R"],glow:["PV_TRUNK"]}},kicker:"Intrahepatic \xB7 presinusoidal",site:"presin",title:"Schistosomiasis: presinusoidal resistance leaves the wedged pressure normal",vignette:"A 26-year-old man who grew up in the Nile Delta presents with hematemesis. EGD shows large esophageal varices. His spleen is enlarged, his liver tests are normal, and there is no ascites.",line:"Schistosome eggs lodge in the portal venules and cause fibrosis upstream of the sinusoids, so the HVPG stays near normal.",notes:"Schistosoma mansoni and japonicum eggs reach the presinusoidal portal venules, where granulomas form and periportal (Symmers) fibrosis follows. The sinusoids and hepatocytes are spared: liver function is preserved, ascites is rare and liver stiffness is near normal. The portal vein is patent on imaging, which distinguishes it from portal vein thrombosis. The HVPG is normal or mildly elevated and underestimates the portal pressure. On the profile the pressure drop is between the portal venules and the sinusoids, still upstream of the sinusoids that the WHVP reflects. The same pattern occurs in porto-sinusoidal vascular disorder, early primary biliary cholangitis, sarcoidosis and congenital hepatic fibrosis.",ask:["A patient bleeds from varices. Doppler shows a patent portal vein; the HVPG is 3 mmHg and the FHVP and right atrial pressure are normal. Where does the resistance lie?","Presinusoidal, in the portal tracts (schistosomiasis or porto-sinusoidal vascular disorder): the WHVP reflects normal sinusoids, and the normal FHVP and right atrial pressure rule out an outflow or cardiac cause."]},{id:"sin",lens:"drop",terms:{sinusoids:"lobule:sinusoid"},preset:"cirr-decomp",cam:"lobule:sinusoid",callout:{at:"sin",label:"Resistance"},tool:e,key:["whvp","hvpg"],scales:{anatomy:{cam:"liver",labels:["CONF","SIN_R","RHV"],glow:["SIN_RR","SIN_LL"]}},kicker:"Intrahepatic \xB7 sinusoidal",site:"sin",title:"Cirrhosis: sinusoidal resistance raises the wedged pressure",vignette:"A 58-year-old man with alcohol-associated cirrhosis has ascites controlled on diuretics and could not take a beta-blocker. His albumin is 2.8 g/dL, his platelets are 60,000/\xB5L, and EGD shows large esophageal varices.",line:"Fibrosis, regenerative nodules and stellate cell contraction narrow the sinusoids. The wedged pressure reflects sinusoidal pressure, so the HVPG rises with portal pressure.",notes:"In cirrhosis the resistance is in the sinusoids: fibrosis, regenerative nodules, a capillarized endothelium and contracted stellate cells, the dynamic part that drugs can relax. Splanchnic vasodilation then raises portal inflow and sustains the pressure. The wedged pressure closely tracks the portal pressure, so the HVPG estimates the portal pressure gradient: \u226510 mmHg is clinically significant portal hypertension (CSPH), and the risk of variceal bleeding rises from about 12 mmHg. In MASLD cirrhosis the WHVP can underestimate the portal pressure, so an HVPG <10 mmHg does not exclude CSPH. On the profile the pressure drop now lies between the sinusoids and the hepatic vein, inside the HVPG bracket. The usual causes are alcohol-associated liver disease, MASLD, hepatitis B and C, and autoimmune, cholestatic and metabolic liver disease.",ask:["Why does the wedged pressure track the portal pressure in cirrhosis?","The resistance is in the sinusoids, which the WHVP reflects, so the wedged pressure rises with the portal pressure."]},{id:"postsin",lens:"drop",terms:{"central veins":"lobule:central",sinusoids:"lobule:sinusoid"},preset:"sos",cam:"lobule:central",callout:{at:"cv",label:"Resistance"},tool:e,key:["whvp","hvpg"],scales:{anatomy:{cam:"liver",labels:["SIN_R","RHV"],glow:["RHV_IVC","MHV_IVC","LHV_IVC"]}},kicker:"Intrahepatic \xB7 postsinusoidal",site:"postsin",title:"Sinusoidal obstruction syndrome: postsinusoidal resistance raises the HVPG",vignette:"A 45-year-old woman, 21 days after myeloablative conditioning for allogeneic HSCT, has tender hepatomegaly, a 4% weight gain and new ascites. Her bilirubin is 2.1 mg/dL.",line:"Sinusoidal endothelial injury raises resistance in the sinusoids and central veins, between the wedged and free positions, so the HVPG rises.",notes:"Formerly called veno-occlusive disease. Toxic injury causes sloughing of sinusoidal endothelial cells, which raises resistance in the sinusoids and the terminal hepatic venules. It presents within weeks of myeloablative conditioning with tender hepatomegaly, weight gain, ascites and jaundice. An HVPG \u226510 mmHg, measured at transjugular biopsy, strongly supports the diagnosis. The model shows an early stage, with an HVPG of about 11 mmHg, just above the 10 mmHg threshold that supports the diagnosis after HSCT. Causes: HSCT conditioning, oxaliplatin and pyrrolizidine alkaloids (bush teas).",ask:["Why does the HVPG rise in sinusoidal obstruction syndrome but not in schistosomiasis?","In sinusoidal obstruction syndrome the resistance is in the sinusoids and central veins, between the wedged and free positions; in schistosomiasis it is in the portal tracts, upstream of them."]},{id:"post",lens:"drop",preset:"budd-chiari",cam:"hepatic",labels:["RHV","RA"],mark:{edges:["RHV_IVC","MHV_IVC","LHV_IVC"],label:"Clot in hepatic veins",free:!0},tool:e,key:["fhvp","ra","hvpg"],kicker:"Post-hepatic",site:"post",title:"Budd\u2013Chiari syndrome: a high PPG, the HVPG near zero",vignette:"A 29-year-old woman with OCP use has had RUQ pain for 2 months and now has tense ascites. Paracentesis shows a SAAG of 1.4 and a total protein of 4.3 g/dL.",line:"Upstream of the thrombosed veins both pressures are high, so the HVPG is near zero; the [right atrium](ra) is {ra}. The [caudate lobe](caudate) drains to the IVC and often hypertrophies.",notes:"Hepatic venous outflow obstruction, anywhere from the small hepatic veins to the IVC at the right atrium. The liver is congested and enlarged; the caudate lobe, which drains directly into the IVC, hypertrophies. Ascites is common and protein-rich (total protein \u22652.5 g/dL), with a SAAG \u22651.1 g/dL. In practice the thrombosed veins often cannot be catheterized; when one can be entered, both readings lie upstream of the resistance. The model shows the pressures there. Doppler ultrasound, CT or MR venography make the diagnosis. On the profile the pressure drop is downstream of the hepatic vein, between it and the IVC, outside the HVPG bracket. On the pressure drop view, the thrombosed veins stand out. Causes: a myeloproliferative neoplasm (JAK2), thrombophilia, pregnancy or OCP use, an IVC web, and tumor invasion of the veins.",ask:["Why is the HVPG near zero although the portal pressure is about 26 mmHg?","Where the catheter reaches upstream of the resistance, both the WHVP and the FHVP are measured there, so both are high and their difference is small."]},{id:"cardiac",lens:"drop",terms:["hv","sin"],preset:"rhf",cam:"heart",labels:["RHV","IVCS","RA"],glow:["ivc","hv"],glowSeq:550,tool:e,key:["fhvp","hvpg","ppg"],compare:[{label:"Normal heart",short:"Normal",preset:"healthy"},{label:"Failing heart",short:"Failing",own:!0}],kicker:"Cardiac",site:"cardiac",title:"Right heart failure: every pressure rises, but neither gradient does",vignette:"A 67-year-old man with severe TR from pulmonary hypertension has an elevated JVP, leg edema and ascites. Paracentesis shows a SAAG of 1.4 and a total protein of 4.3 g/dL, and EGD shows no varices.",line:"Elevated [right atrial pressure](ra) is transmitted back through the hepatic veins to the sinusoids, so every pressure rises together: a high portal pressure, but neither gradient rises.",notes:"Congestive hepatopathy. The JVP is elevated, hepatojugular reflux is positive and Doppler shows pulsatile portal venous flow. The ascites is protein-rich, with a SAAG \u22651.1 g/dL. Varices are rare: they require a portal pressure gradient, and here both the portal and the systemic venous pressures are high, so the PPG is normal. Constrictive pericarditis gives the same pattern with a normal-sized heart. No vessel stands out on the figure because the resistance is cardiac. Causes: tricuspid regurgitation, pulmonary hypertension, left heart failure and constrictive pericarditis. Tap Normal heart and the whole profile returns to the dashed healthy line.",ask:["Why are varices rare in right heart failure despite a portal pressure of about 20 mmHg?","Varices require a portal pressure gradient; the systemic venous pressure is elevated as well, so the PPG is normal."]},{id:"steps",preset:"cirr-decomp",cam:"fit",tool:{kind:"causes",metric:"ppg"},data:"tiles",tiles:["ppg","hvpg"],key:["ppg"],compare:[{label:"Portal vein thrombosis",short:"Clot",preset:"pvt-chronic"},{label:"Schistosomiasis",short:"Schisto",preset:"schisto"},{label:"Cirrhosis",own:!0},{label:"Sinusoidal obstruction",short:"SOS",preset:"sos"},{label:"Budd\u2013Chiari syndrome",short:"Budd\u2013Chiari",preset:"budd-chiari"},{label:"Right heart failure",short:"Heart",preset:"rhf"}],kicker:"How to tell them apart",title:"Each site builds the PPG from its own steps",line:"The resistance is the largest step to the right, and collaterals offset part of it. In right heart failure the large steps go left.",notes:"Each bar is one cause of the patient's PPG, calculated by the model by removing that cause. Tap a patient to see the steps. In portal vein thrombosis it is the thrombus, in schistosomiasis the resistance in the portal venules, in cirrhosis the resistance in the sinusoids, in sinusoidal obstruction syndrome the resistance just downstream of them, and in Budd\u2013Chiari the hepatic vein thrombosis. Collaterals offset part of the gradient in each. In right heart failure the IVC pressure that the PPG subtracts is elevated, so the steps go left and the PPG is normal. AASLD 2024 Table 1 sorts portal hypertension by where the resistance lies. The sizes of the steps are the model's own, not published figures.",ask:["Which step is largest in cirrhosis, and which patient's steps go left?","The resistance in the sinusoids is the largest step to the right. In right heart failure the steps go left: the elevated pressure downstream of the liver is subtracted, so the PPG is normal."]},{id:"ladders",cam:"fit",visual:"ladders",of:r,question:"Which of the six raised the HVPG?",kicker:"How to tell them apart",title:"The biggest pressure drop shows where the resistance is",notes:"Read each ladder from left to right. Prehepatic and presinusoidal: the pressure drop is upstream of the sinusoids that the WHVP reflects, so the HVPG is normal and only a direct portal pressure (or the PPG) shows it. Sinusoidal and postsinusoidal: the drop lies inside the HVPG bracket, which is what the HVPG measures. Post-hepatic: the drop is downstream of the hepatic vein. Cardiac: there is no focal drop; every pressure is high.",ask:["Which two levels raise the HVPG?","Sinusoidal and postsinusoidal: only there does the resistance lie between the wedged and free positions."]},{id:"relation",cam:"fit",visual:"plane",plane:"hvpg-ppg",of:[{id:"healthy",name:"Healthy"},{id:"pvt",name:"Portal vein thrombosis",short:"PVT"},{id:"presin",name:"Schistosomiasis",short:"Schisto"},{id:"sin",name:"Cirrhosis"},{id:"postsin",name:"Sinusoidal obstruction",short:"SOS"},{id:"post",name:"Budd\u2013Chiari"},{id:"cardiac",name:"Heart failure"}],kicker:"Summary",title:"Each site occupies its own region of the HVPG\u2013PPG plane",line:"Portal vein thrombosis, schistosomiasis and Budd\u2013Chiari raise the PPG and leave the HVPG normal. Cirrhosis and sinusoidal obstruction syndrome raise both. Right heart failure raises neither.",notes:"Each point is one patient from this talk, plotted with the HVPG on the x-axis and the PPG on the y-axis, with the app's cut-offs (HVPG 5 and 10 mmHg, PPG 6 and 12 mmHg). The HVPG 10 line marks clinically significant portal hypertension (CSPH: an HVPG of 10 mmHg or more, Baveno VIII and AASLD 2024), and an HVPG to its right is CSPH, whatever the PPG. The PPG 12 line marks the bleeding risk and the post-TIPS target (<12 mmHg); it is not a CSPH cut-off. Prehepatic and presinusoidal resistance lies upstream of the wedged position, so the HVPG stays normal while the PPG rises. Sinusoidal and postsinusoidal resistance lies inside the HVPG bracket, so both rise. In Budd\u2013Chiari the hepatic veins cannot be wedged at all; the model's HVPG there is a value no catheter can measure. In right heart failure every pressure is high, but neither gradient rises. (AASLD 2024 Table 1; Baveno VIII Table 3; EASL 2025: the HVPG misses the portal hypertension of portal vein thrombosis and PSVD.)",ask:["A patient has varices, an HVPG of 3 mmHg and a PPG of 15 mmHg. Which sites fit?","Prehepatic or presinusoidal (portal vein thrombosis, schistosomiasis), or Budd\u2013Chiari."]},{id:"summary",visual:"table",cols:["pv","whvp","fhvp","ra","hvpg","ppg"],asc:!0,of:[{preset:"healthy",kicker:"Reference",title:"Healthy",ref:!0},...o],kicker:"Summary",title:"The HVPG rises only with sinusoidal and postsinusoidal resistance",line:"Portal pressure is high at every site. For the other levels, measure the PPG, the FHVP and the right atrial pressure.",notes:"Portal pressure is high at every level. The HVPG is elevated only when the resistance lies between the wedged and free positions (sinusoidal, postsinusoidal). A SAAG \u22651.1 g/dL confirms portal hypertension as the cause of ascites; the ascitic total protein then separates cirrhosis (low, <2.5 g/dL) from hepatic venous outflow obstruction and cardiac ascites (high). Prehepatic and presinusoidal disease rarely cause ascites, because the sinusoids, where ascites forms, are at normal pressure. The model gives sinusoidal obstruction syndrome a protein-rich ascites; reports in patients vary. The Where is the resistance? talk gives six unnamed patients to place on these same sites, as practice after this one.",ask:["A patient has ascites with a SAAG of 1.6 and a total protein of 4 g/dL before any diuretic. Which levels fit best?","Post-hepatic or cardiac (Budd\u2013Chiari, right heart failure), or sinusoidal obstruction syndrome."]}]};export{n as a};
